namespace RonSijm.FluidHumidifier.Factories.S3Tables;

public class TableFactory(string resourceName = null, Action<Humidifier.S3Tables.Table> factoryAction = null) : ResourceFactory<Humidifier.S3Tables.Table>(resourceName)
{

    internal InnerTableStorageClassConfigurationFactory StorageClassConfigurationFactory { get; set; }

    internal InnerTableIcebergMetadataFactory IcebergMetadataFactory { get; set; }

    internal InnerTableCompactionFactory CompactionFactory { get; set; }

    internal InnerTableSnapshotManagementFactory SnapshotManagementFactory { get; set; }

    protected override Humidifier.S3Tables.Table Create()
    {
        var tableResult = CreateTable();
        factoryAction?.Invoke(tableResult);

        return tableResult;
    }

    private Humidifier.S3Tables.Table CreateTable()
    {
        var tableResult = new Humidifier.S3Tables.Table
        {
            GivenName = InputResourceName,
        };

        return tableResult;
    }
    public override void CreateChildren(Humidifier.S3Tables.Table result)
    {
        base.CreateChildren(result);

        result.StorageClassConfiguration ??= StorageClassConfigurationFactory?.Build();
        result.IcebergMetadata ??= IcebergMetadataFactory?.Build();
        result.Compaction ??= CompactionFactory?.Build();
        result.SnapshotManagement ??= SnapshotManagementFactory?.Build();
    }

} // End Of Class

